"use strict";(self.webpackChunkmos_docs=self.webpackChunkmos_docs||[]).push([["5632"],{55256(e){e.exports=JSON.parse('{"title":"Glossary","description":"Key terms used in MOS and its documentation.","terms":[{"term":"API Token","aliases":["Bearer token","Admin API token"],"definition":"A token created under Settings > Network > Token that authenticates requests to the MOS API from outside the WebUI.","documentation":{"path":"/docs/Settings/Network/Token","label":"Token management"},"relatedTerms":["MOS API"],"autoLink":false},{"term":"Appdata","aliases":["AppData","Application data"],"definition":"The directory where Docker containers keep their persistent configuration and data. It must live on a storage pool and should be backed up regularly.","documentation":{"path":"/docs/Docker/Docker-Service","label":"Docker Service settings"},"relatedTerms":["Docker","Pool"],"autoLink":false},{"term":"bcachefs","definition":"A copy-on-write filesystem with checksums and optional replication, available as a MOS pool type.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"bcachefs pools"},"relatedTerms":["Pool","Scrub"],"autoLink":false},{"term":"Bond","definition":"Combines two or more physical network interfaces into one logical interface for redundancy or throughput. The switch must be configured to match (LACP or static).","documentation":{"path":"/docs/Settings/Network/Network-Configuration","label":"Network configuration"},"relatedTerms":["Bridge"],"autoLink":false},{"term":"Boot device","aliases":["Boot stick","Boot medium","USB stick"],"definition":"The USB stick or internal disk MOS boots from. Persistent system configuration lives in /boot/config on this device.","documentation":{"path":"/docs/Installation/Create-Bootable-Media","label":"Create bootable media"},"relatedTerms":["Diagnostics"],"autoLink":false},{"term":"Bridge","aliases":["br0","Bridged"],"definition":"A virtual network switch that connects virtual machines and containers to the physical LAN. The recommended interface type for most MOS installations.","documentation":{"path":"/docs/Settings/Network/Network-Configuration","label":"Network configuration"},"relatedTerms":["Bond","VLAN","KVM/QEMU","LXC"],"autoLink":false},{"term":"Btrfs","definition":"A copy-on-write Linux filesystem with snapshots and checksums. Can be used as a pool filesystem and is required for snapshot-based LXC backups.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"Pool filesystems"},"relatedTerms":["Snapshot","Scrub","Pool"],"autoLink":false},{"term":"CHAP","definition":"Challenge Handshake Authentication Protocol. Used to authenticate an iSCSI initiator against a target.","documentation":{"path":"/docs/Settings/Network/iSCSI-Target","label":"iSCSI Target"},"relatedTerms":["iSCSI","IQN"],"autoLink":false},{"term":"Diagnostics","definition":"A downloadable .tar.gz archive containing system information, logs and configuration. Attach it when asking for support.","documentation":{"path":"/docs/Troubleshooting/Diagnostics","label":"Create a diagnostics file"},"relatedTerms":["Boot device"],"autoLink":false},{"term":"Dnsmasq","definition":"A lightweight DNS forwarder and DHCP server that MOS can enable for the local network.","documentation":{"path":"/docs/Settings/Network/Network-Services","label":"Network Services"},"relatedTerms":["Bridge"],"autoLink":false},{"term":"Docker","definition":"The container runtime MOS uses for applications. It is enabled and configured under Settings > Virtualization > Docker Service.","documentation":{"path":"/docs/Docker/Docker-Service","label":"Docker Service"},"relatedTerms":["Docker Template","Docker Compose","Appdata","MOS Hub"],"autoLink":false},{"term":"Docker Compose","aliases":["Compose","Compose stack"],"definition":"A multi-container stack defined in a compose.yaml file. MOS Hub can deploy Compose stacks as a single app.","documentation":{"path":"/docs/MOS-Hub/Creating-Your-Own-MOS-Hub-Repository","label":"Compose templates"},"relatedTerms":["Docker","Docker Template","MOS Hub"],"autoLink":false},{"term":"Docker Template","aliases":["Container template"],"definition":"A JSON file describing a container (image, ports, volumes, environment). MOS saves one automatically for every container you create.","documentation":{"path":"/docs/Docker/Start-the-First-Container","label":"Start the first container"},"relatedTerms":["Docker","Docker Compose","MOS Hub"],"autoLink":false},{"term":"Firmware","aliases":["MOS firmware","System image"],"definition":"In MOS, the complete system image including the OS and kernel that is installed on the boot device and updated through Settings > System > Update System.","documentation":{"path":"/docs/Settings/System/Update-System","label":"Update System"},"relatedTerms":["Update channel","Boot device"],"autoLink":false},{"term":"FSNavigator","definition":"Internal name of the Filebrowser service. The WebUI calls it Filebrowser; the API endpoints use fsnavigator.","documentation":{"path":"/docs/Filebrowser/","label":"Filebrowser"},"relatedTerms":["WebUI"],"autoLink":false},{"term":"Hub Repository","aliases":["MOS Hub repository","Template repository"],"definition":"A GitHub repository in the layout the MOS Hub expects (docker/, compose/, plugins/) that can be added as a template source.","documentation":{"path":"/docs/MOS-Hub/Creating-Your-Own-MOS-Hub-Repository","label":"Create your own repository"},"relatedTerms":["MOS Hub","Docker Template","Docker Compose","Plugin"],"autoLink":false},{"term":"iSCSI","definition":"A protocol that shares block storage over the network. MOS can export storage as a target and mount remote targets as an initiator.","documentation":{"path":"/docs/Settings/Network/iSCSI-Target","label":"iSCSI Target"},"relatedTerms":["IQN","LUN","CHAP"],"autoLink":false},{"term":"IQN","abbreviation":"iSCSI Qualified Name","definition":"The unique identifier of an iSCSI target or initiator. The initiator IQN is generated automatically by MOS.","documentation":{"path":"/docs/Settings/Network/iSCSI-Target","label":"Target IQN format"},"relatedTerms":["iSCSI","LUN"],"autoLink":false},{"term":"KVM/QEMU","aliases":["QEMU","KVM","Virtual machine"],"definition":"The full-virtualization stack used for MOS virtual machines. VMs are enabled under Settings > Virtualization > VM Service.","documentation":{"path":"/docs/VMs/VM-Service","label":"VM Service"},"relatedTerms":["VirtIO","OVMF","PCI Passthrough","Bridge"],"autoLink":false},{"term":"LUN","abbreviation":"Logical Unit Number","definition":"A block device exported by an iSCSI target. Each LUN is backed by a disk, partition or image file on the MOS server.","documentation":{"path":"/docs/Settings/Network/iSCSI-Target","label":"LUNs"},"relatedTerms":["iSCSI","IQN"],"autoLink":false},{"term":"LXC","abbreviation":"Linux Containers","definition":"Lightweight OS-level virtualization that shares the host kernel. Containers are managed on the LXC page and enabled under Settings > Virtualization > LXC Service.","documentation":{"path":"/docs/LXC/LXC-Service","label":"LXC Service"},"relatedTerms":["Snapshot","Bridge","Docker"],"autoLink":false},{"term":"mergerfs","definition":"A union filesystem that combines several disks into one mountpoint. Often combined with SnapRAID.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"mergerfs pools"},"relatedTerms":["SnapRAID","Pool","Virtual Pool"],"autoLink":false},{"term":"MFA","aliases":["2FA","Two-factor authentication","TOTP"],"definition":"Multi-factor authentication using a TOTP app in addition to the password. Each account also gets recovery codes for when the app is unavailable.","documentation":{"path":"/docs/Settings/User-Management/User-Profile","label":"User profile and MFA"},"autoLink":false},{"term":"Minimal Free Space","definition":"The free-space threshold at which MOS stops writing to a disk and moves on to the next disk in a mergerfs or nonraid pool.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"Pool configuration fields"},"relatedTerms":["Pool","mergerfs","nonraid"],"autoLink":false},{"term":"MOS API","aliases":["REST API","MOS Admin API"],"definition":"The REST API used by the WebUI and available for automation. Interactive documentation (Swagger UI) is served at /api-docs/ on the MOS IP.","documentation":{"path":"/docs/API/MOS-API-Overview","label":"API overview"},"relatedTerms":["API Token","Rate limit","WebUI"],"autoLink":false},{"term":"MOS Hub","definition":"MOS app catalog for installing Docker containers, Compose stacks and plugins.","documentation":{"path":"/docs/MOS-Hub/MOS-Hub-Settings","label":"MOS Hub settings"},"relatedTerms":["Docker Template","Docker Compose","Plugin","Hub Repository"],"autoLink":false},{"term":"Netbird","definition":"An open-source mesh VPN based on WireGuard that MOS can enable as an alternative to Tailscale.","documentation":{"path":"/docs/Settings/Network/Network-Services","label":"Network Services"},"relatedTerms":["Tailscale"],"autoLink":false},{"term":"NFS","abbreviation":"Network File System","definition":"The file-sharing protocol used to mount MOS shares on Linux and Unix clients.","documentation":{"path":"/docs/Settings/Network/Network-Services","label":"Network Services"},"relatedTerms":["Share","SMB"],"autoLink":false},{"term":"nonraid","definition":"A pool type with dedicated parity disks, similar to Unraid. Requires the nonraid driver, which is installed from the MOS Hub.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"nonraid pools"},"relatedTerms":["Parity","Resync","Pool","Plugin"],"autoLink":false},{"term":"NUT","abbreviation":"Network UPS Tools","definition":"The service MOS uses to monitor a UPS and trigger a graceful shutdown when mains power is lost.","documentation":{"path":"/docs/Settings/Network/Network-Services","label":"NUT configuration"},"relatedTerms":["UPS","Spindown"],"autoLink":false},{"term":"OVMF","definition":"The UEFI firmware used by virtual machines. Required for Windows 11 and modern Linux distributions.","documentation":{"path":"/docs/VMs/Create-the-First-VM","label":"Create the first VM"},"relatedTerms":["KVM/QEMU","VirtIO"],"autoLink":false},{"term":"Parity","definition":"Redundant data stored on one or more parity disks so a failed data disk can be rebuilt. Parity disks hold no usable capacity. Used by SnapRAID and nonraid.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"Parity setup"},"relatedTerms":["nonraid","SnapRAID","RAID","Resync"],"autoLink":false},{"term":"PCI Passthrough","aliases":["GPU passthrough","Device passthrough"],"definition":"Giving a virtual machine exclusive access to a physical PCI device such as a GPU or controller. The host cannot use the device while the VM runs.","documentation":{"path":"/docs/VMs/Create-the-First-VM","label":"PCI passthrough"},"relatedTerms":["KVM/QEMU"],"autoLink":false},{"term":"Plugin","aliases":["Driver Plugin","MOS Plugin"],"definition":"An installable extension from the MOS Hub. Drivers are distributed as plugins, and some plugins add their own page to the WebUI.","documentation":{"path":"/docs/Plugins/Drivers","label":"Drivers and plugins"},"relatedTerms":["MOS Hub","Hub Repository"],"autoLink":false},{"term":"Pool","definition":"One or more disks managed together as a single storage area. MOS supports single, multi, mergerfs, nonraid and bcachefs pools, plus Virtual Pools built from existing paths.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"Create a storage pool"},"relatedTerms":["Share","Virtual Pool","RAID","Parity"],"autoLink":false},{"term":"PWA","abbreviation":"Progressive Web App","definition":"A website that can be installed as an app. MOS Docs can be installed and cached for offline reading.","documentation":{"path":"/docs/Dashboard/WebUI-Overview","label":"WebUI overview"},"autoLink":false},{"term":"RAID","abbreviation":"Redundant Array of Independent Disks","definition":"Combining several disks into one protected volume. MOS multi pools support RAID 0 (striping, no protection) and RAID 1 (mirroring).","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"RAID levels"},"relatedTerms":["Parity","Pool"],"autoLink":false},{"term":"Rate limit","aliases":["Rate limiting"],"definition":"Protection that caps API requests at 20 per second by default. The defaults are tuned for stability and should not be changed.","documentation":{"path":"/docs/API/Rate-Limits","label":"API rate limits"},"relatedTerms":["MOS API"],"autoLink":false},{"term":"Resync","definition":"Rebuilding parity, or rebuilding a replaced data disk from parity. A nonraid pool is usable during the initial resync but not yet protected.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"Parity maintenance"},"relatedTerms":["Parity","nonraid","SnapRAID"],"autoLink":false},{"term":"samba_only","definition":"A user role without WebUI access. The account can only authenticate against file shares.","documentation":{"path":"/docs/Settings/User-Management/Users","label":"User roles"},"relatedTerms":["Share","SMB"],"autoLink":false},{"term":"Scrub","definition":"A maintenance task that reads all data and verifies it against stored checksums, repairing from a mirror where possible. Available for btrfs and bcachefs.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"Scrub"},"relatedTerms":["Btrfs","bcachefs","Snapshot"],"autoLink":false},{"term":"Share","definition":"A folder on a pool that is shared over SMB or NFS.","documentation":{"path":"/docs/Shares/Create-the-First-Shares","label":"Create the first shares"},"relatedTerms":["SMB","NFS","Pool","samba_only"],"autoLink":false},{"term":"SMB","aliases":["Samba","CIFS"],"definition":"The Windows file-sharing protocol. MOS provides SMB shares through Samba.","documentation":{"path":"/docs/Settings/Network/Network-Services","label":"Samba"},"relatedTerms":["Share","NFS","samba_only"],"autoLink":false},{"term":"SMART","aliases":["S.M.A.R.T."],"definition":"Self-Monitoring, Analysis and Reporting Technology. Disk health data used for warnings and temperature limits.","documentation":{"path":"/docs/Disks/SMART","label":"S.M.A.R.T. settings"},"relatedTerms":["Spindown"],"autoLink":false},{"term":"SnapRAID","definition":"Parity-based protection for mergerfs pools. It is not a live RAID; parity is updated on a schedule.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"SnapRAID parity"},"relatedTerms":["mergerfs","Parity","Resync"],"autoLink":false},{"term":"Snapshot","definition":"A point-in-time copy of a container or VM disk used for backups and rollback. LXC snapshot backups require btrfs storage; VM snapshots require qcow2 disks.","documentation":{"path":"/docs/LXC/LXC-Service","label":"Backups and snapshots"},"relatedTerms":["Btrfs","LXC","KVM/QEMU"],"autoLink":false},{"term":"Spindown","definition":"Putting idle disks into standby after a configured number of minutes to save power and reduce noise.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"Spindown settings"},"relatedTerms":["SMART","Pool"],"autoLink":false},{"term":"Swapfile","definition":"A file on disk used as virtual memory when physical RAM is exhausted. Configured under Settings > System Configuration > System.","documentation":{"path":"/docs/Settings/System-Configuration/System","label":"Swapfile settings"},"relatedTerms":["Zswap","ZRAM"],"autoLink":false},{"term":"Tailscale","definition":"A WireGuard-based mesh VPN that gives remote access to MOS without port forwarding.","documentation":{"path":"/docs/Settings/Network/Network-Services","label":"Network Services"},"relatedTerms":["Netbird"],"autoLink":false},{"term":"Update channel","aliases":["Release channel","Stable","Beta","Alpha"],"definition":"The firmware track MOS follows: alpha (team testing only), beta (pre-release) or stable (recommended for production).","documentation":{"path":"/docs/Settings/System/Update-System","label":"Update System"},"relatedTerms":["Boot device"],"autoLink":false},{"term":"UPS","abbreviation":"Uninterruptible Power Supply","definition":"A battery backup that keeps the server running during a power outage. MOS monitors it through NUT and can shut down gracefully.","documentation":{"path":"/docs/Settings/Network/Network-Services","label":"NUT (UPS)"},"relatedTerms":["NUT","Spindown"],"autoLink":false},{"term":"Virtual Pool","aliases":["vpool"],"definition":"A pool built from existing directory paths (for example /mnt/main and /mnt/media) combined with mergerfs. No dedicated disks and no formatting required.","documentation":{"path":"/docs/Pools/Virtual-Pools","label":"Virtual Pools"},"relatedTerms":["mergerfs","Pool"],"autoLink":false},{"term":"VirtIO","definition":"Paravirtualized disk and network drivers for virtual machines. They offer the best performance and need separate drivers inside Windows guests.","documentation":{"path":"/docs/VMs/Create-the-First-VM","label":"VirtIO drivers"},"relatedTerms":["KVM/QEMU","OVMF"],"autoLink":false},{"term":"VLAN","definition":"A tagged (802.1Q) network segment configured on an interface. A VLAN can carry its own IP or be used only for bridging.","documentation":{"path":"/docs/Settings/Network/Network-Configuration","label":"VLAN configuration"},"relatedTerms":["Bridge","Bond"],"autoLink":false},{"term":"WebUI","aliases":["Web UI","Frontend","Web interface"],"definition":"The MOS browser interface. It performs no direct system actions; every action goes through the MOS API.","documentation":{"path":"/docs/Dashboard/WebUI-Overview","label":"WebUI overview"},"relatedTerms":["MOS API","FSNavigator"],"autoLink":false},{"term":"XFS","definition":"A journaling filesystem recommended for mergerfs and nonraid data disks.","documentation":{"path":"/docs/Pools/Create-Storage-Pool","label":"Pool filesystems"},"relatedTerms":["Pool","mergerfs","nonraid"],"autoLink":false},{"term":"ZFS","aliases":["OpenZFS"],"definition":"A copy-on-write filesystem with snapshots, checksums and RAID-Z. Available through the OpenZFS Driver plugin and currently CLI only.","documentation":{"path":"/docs/Pools/ZFS","label":"ZFS in MOS"},"relatedTerms":["Plugin","Scrub"],"autoLink":false},{"term":"ZRAM","definition":"A compressed block device in RAM used as compressed swap or as a fast RAM disk.","documentation":{"path":"/docs/Settings/Hardware/ZRAM","label":"ZRAM settings"},"relatedTerms":["Zswap","Swapfile"],"autoLink":false},{"term":"Zswap","definition":"A kernel feature that compresses memory pages in RAM before they are written to swap.","documentation":{"path":"/docs/Settings/System-Configuration/System","label":"Zswap settings"},"relatedTerms":["ZRAM","Swapfile"],"autoLink":false}]}')}}]);